const cfg = $json || {};
const prepared = {
  locationId: String(cfg.locationId || '').trim(),
  locationName: String(cfg.locationName || '').trim(),
  timezone: String(cfg.timezone || 'America/Los_Angeles').trim(),
  reportHost: String(cfg.reportHost || 'https://reports.livetransparent.com').trim(),
  embedUrl: String(cfg.embedUrl || 'https://reports.livetransparent.com/embed/executive').trim(),
  defaultRange: String(cfg.defaultRange || '30d').trim(),
  ga4MeasurementId: String(cfg.ga4MeasurementId || '').trim(),
  ga4StreamId: String(cfg.ga4StreamId || '').trim(),
  ga4PropertyId: String(cfg.ga4PropertyId || '').trim(),
  gscProperty: String(cfg.gscProperty || '').trim(),
  preparedState: String(cfg.preparedState || 'ga4_enabled').trim(),
  updatedAt: new Date().toISOString(),
};
function jsonbLiteral(value) { return "'" + JSON.stringify(value).replace(/'/g, "''") + "'::jsonb"; }
const runtimeConfig = {
  locationId: prepared.locationId, locationName: prepared.locationName, timezone: prepared.timezone,
  reportHost: prepared.reportHost, embedUrl: prepared.embedUrl, defaultRange: prepared.defaultRange,
  ga4MeasurementId: prepared.ga4MeasurementId, ga4StreamId: prepared.ga4StreamId,
  ga4PropertyId: prepared.ga4PropertyId || null, gscProperty: prepared.gscProperty || null,
  preparedState: prepared.preparedState, status: prepared.ga4PropertyId ? 'ready_for_ga4' : 'waiting_for_ga4_property_id',
};
const reportConfigSql = "INSERT INTO report_config (config_key, config_value, notes, updated_at) VALUES ('report_runtime', " + jsonbLiteral(runtimeConfig) + ", 'LiveTransparent reporting runtime config', NOW()) ON CONFLICT (config_key) DO UPDATE SET config_value = EXCLUDED.config_value, notes = EXCLUDED.notes, updated_at = NOW();";
const healthRows = [
  { source_system: 'ga4', status: prepared.ga4PropertyId ? 'ready' : 'blocked', last_error: prepared.ga4PropertyId ? null : 'GA4 property ID is now configured', metadata: { ready: !!prepared.ga4PropertyId, dependency: prepared.ga4PropertyId ? null : 'ga4_property_id', measurementId: prepared.ga4MeasurementId, streamId: prepared.ga4StreamId } },
  { source_system: 'gsc', status: 'ready', last_error: null, metadata: { ready: true, note: 'Search Console layer can be prepared independently.' } },
  { source_system: 'ghl', status: 'ready', last_error: null, metadata: { ready: true, note: 'CRM layer is available now.' } },
];
const sourceHealthSql = "INSERT INTO report_source_health (source_system, status, last_attempt_at, last_error, metadata, updated_at) VALUES " + healthRows.map(row => "(" + [jsonbLiteral(row.source_system), jsonbLiteral(row.status), 'NOW()', row.last_error ? jsonbLiteral(row.last_error) : 'NULL', jsonbLiteral(row.metadata), 'NOW()'].join(', ') + ")").join(",\n") + " ON CONFLICT (source_system) DO UPDATE SET status = EXCLUDED.status, last_attempt_at = EXCLUDED.last_attempt_at, last_error = EXCLUDED.last_error, metadata = EXCLUDED.metadata, updated_at = NOW();";
return [{ json: { ...prepared, runtimeConfig, upsertSql: reportConfigSql + "\n\n" + sourceHealthSql } }];

